package jp.wakeguard.alarm;
import android.appwidget.*;import android.content.*;import android.widget.RemoteViews;import java.util.*;
public class AlarmListWidgetProvider extends AppWidgetProvider{
 static void update(Context c,AppWidgetManager m,int id){RemoteViews r=new RemoteViews(c.getPackageName(),R.layout.widget_alarm_list);List<AlarmStore.Entry> a=WidgetSuite.enabledAlarms(c);int[] t={R.id.a1_time,R.id.a2_time,R.id.a3_time,R.id.a4_time},n={R.id.a1_name,R.id.a2_name,R.id.a3_name,R.id.a4_name};for(int i=0;i<4;i++){if(i<a.size()){AlarmStore.Entry e=a.get(i);r.setTextViewText(t[i],String.format(Locale.US,"%02d:%02d",e.hour,e.minute));r.setTextViewText(n[i],WidgetSuite.alarmLabel(e));}else{r.setTextViewText(t[i],"--:--");r.setTextViewText(n[i],i==0?I18n.tr(c,"アラームなし"):"");}}r.setOnClickPendingIntent(R.id.widget_root,WidgetSuite.open(c,MainActivity.class,null,null,23000+id));r.setOnClickPendingIntent(R.id.widget_add,WidgetSuite.open(c,AlarmEditorActivity.class,null,null,23100+id));m.updateAppWidget(id,r);}public void onUpdate(Context c,AppWidgetManager m,int[] ids){for(int id:ids)update(c,m,id);}public void onAppWidgetOptionsChanged(Context c,AppWidgetManager m,int id,android.os.Bundle b){update(c,m,id);}}
